earth['uncertainties'].append('The Bots and the Bees supplies occupational/family detail, not a second material allocation regime.')
d=deepcopy(D['decisions']['c0479']);d.update(status='duplicate',society_id=earth['id'],reassessed_on=DATE,current_policy_review=True,
 reason='Same recurring Earth robot/human labor order as c0477; parenthood and vocational identity do not establish a material access or control change.',
 analysis='Bender and Ben perform meaningful vocational activity. That detail strengthens the retained work interpretation but does not create another society.',
 follow_up='Resolved model overlap; retain as related evidence without increasing the target count.')
changes.append(change(D,'decisions',d))

d=deepcopy(D['decisions']['c0461'])
d.update(status='boundary_case',reassessed_on=DATE,current_policy_review=True,assessment_mode='best_guess',
 reason='Completed comparison: robotic hunters and surviving scavengers are depicted after collapse, without a continuing productive or supported recipient community.',
 analysis='''The dogs hunt surviving humans in a collapsed world. This demonstrates dangerous independent machinery and technological denial of access, but no continuing community whose necessities are supplied by the dogs or their productive system. The survivors’ effort to obtain stored goods is real activity, and deaths do not become people freed from labor. The case is therefore analyzed as a collapse comparison rather than left awaiting deeper lore reading.

 The comparison coordinates use extremely weak security, strong autonomous-machine dominance and a low nonworking scenario among living survivors who scavenge and care for one another. Control here describes coercive dominance rather than verified ownership of a productive economy. Wide intervals keep that limitation visible. The stored stock and active hunters are not treated as proof that a new civilization is automatically producing goods. This definite mechanism difference keeps the case outside the target; it is not omitted merely because its welfare laws or precise work census are unknown.''',
 follow_up='Completed current-policy collapse comparison; no deep reading requested.',
 comparison_assessment=dict(name='Black Mirror (Metalhead collapse)',media=['tv'],scope='Living human survivors under robotic hunting; coercive dominance rather than an established productive polity',axis=dict(guarantees=.98,control=-.9,nonworking=.15),intervals=dict(guarantees=[.8,1],control=[-1,-.4],nonworking=[0,.6]),confidence='low',canon_facts=['Autonomous robotic dogs hunt human survivors after societal collapse.'],editorial_assumptions=['Control measures coercive machine dominance in this comparison, not verified productive ownership.','The low nonworking scenario retains scavenging and useful care among living survivors.'],source_ids=d['source_ids'],counted_toward_goal=False))
changes.append(change(D,'decisions',d))
for r in records:changes.extend([change(D,'societies',r),change(D,'decisions',retained_decision(r,r['qualification_basis']))])
assert len(records)==12,len(records)
write_revision(15,changes,'Twelve known screen/game cases retained with explicit best guesses. Megazone’s physical residents and BLAME!’s posthuman cyborgs are distinguished from uploaded humans or independent AI. The Bots and the Bees is resolved as an Earth-model duplicate; Metalhead receives a completed collapse comparison.')
